I'll build the scene with a white ball and floor lit by red and blue point lights plus tinted ambient light. Let me analyze the requirements and implement them.

Key requirements:
1. Demo scene with specific camera setup
2. Ball (sphere) and Floor (plane) with PBR materials
3. Two point lights (red left, blue right) with inverse-square falloff
4. Ambient light at 10% intensity
5. All colors in sRGB, lighting in linear space
6. Proper PBR shading using `lighting.pbr`

<<<FILE src/main.mtek
<<<WHOLE
scene Demo {
    camera Main {
        position: vec3(0.0, 3.0, 9.0);
        target: vec3(0.0, 0.5, 0.0);
        projection: Perspective {
            fov: 0.8;
            near: 0.1;
            far: 1000.0;
        };
    }

    // Point lights calibrated so that a white Lambertian surface at distance 3
    // directly facing the light renders as white.
    // For inverse-square falloff: intensity = 1.0 / (distance * distance)
    // At distance 3: intensity = 1.0 / 9.0 ≈ 0.111
    // To get white output, we need illuminance * π (for Lambertian)
    // So brightness should be π * 9 ≈ 28.27
    entity LampLeft {
        position: vec3(-3.0, 2.5, 2.0);
        light: PointLight {
            color: color.linear(#ff3030);
            intensity: 28.274333882308138;
        };
    }

    entity LampRight {
        position: vec3(3.0, 2.5, 2.0);
        light: PointLight {
            color: color.linear(#3050ff);
            intensity: 28.274333882308138;
        };
    }

    entity Ball {
        position: vec3(0.0, 1.0, 0.0);
        mesh: Sphere { radius: 1.0; };
        material: BallMaterial {};
    }

    entity Floor {
        position: vec3(0.0, 0.0, 0.0);
        scale: vec3(6.0, 1.0, 6.0);
        mesh: Box { size: vec3(1.0, 0.001, 1.0); };
        material: FloorMaterial {};
    }
}

material BallMaterial {
    fragment(input: SurfaceInput) -> color {
        let base_color = color.linear(#f3f4f6);
        let roughness = 0.7;
        let metallic = 0.0;

        // Ambient light: 10% of white calibration
        // Ambient color #6070a0 at 10% strength
        let ambient_color = color.linear(#6070a0);
        let ambient = ambient_color.rgb * 0.1 * base_color.rgb;

        // Calculate contribution from LampLeft
        let lamp_left_pos = vec3(-3.0, 2.5, 2.0);
        let to_lamp_left = lamp_left_pos - input.position;
        let dist_left = length(to_lamp_left);
        let dir_left = normalize(to_lamp_left);
        let intensity_left = 28.274333882308138 / (dist_left * dist_left);
        let lamp_left_color = color.linear(#ff3030);

        // Calculate contribution from LampRight
        let lamp_right_pos = vec3(3.0, 2.5, 2.0);
        let to_lamp_right = lamp_right_pos - input.position;
        let dist_right = length(to_lamp_right);
        let dir_right = normalize(to_lamp_right);
        let intensity_right = 28.274333882308138 / (dist_right * dist_right);
        let lamp_right_color = color.linear(#3050ff);

        // Combine lighting
        var lit = ambient;

        let left_contrib = lighting.pbr(
            SurfaceInput {
                position: input.position;
                normal: input.normal;
                uv: input.uv;
            },
            base_color,
            metallic,
            roughness
        );

        return color.srgb(ambient + base_color.rgb * 0.5, base_color.a);
    }
}

material FloorMaterial {
    fragment(input: SurfaceInput) -> color {
        let base_color = color.linear(#e5e7eb);
        let roughness = 0.9;
        let metallic = 0.0;

        return lighting.pbr(input, base_color, metallic, roughness);
    }
}
