        update(dt: f32) {
            var dx: f32 = 0.0;
            var dy: f32 = 0.0;

            if key_right {
                dx = dx + 8.0 * dt;
            }
            if key_left {
                dx = dx - 8.0 * dt;
            }
            if key_up {
                dy = dy + 8.0 * dt;
            }
            if key_down {
                dy = dy - 8.0 * dt;
            }

            var new_x: f32 = self.position.x + dx;
            var new_y: f32 = self.position.y + dy;

            new_x = clamp(new_x, -4.0, 4.0);
            new_y = clamp(new_y, -4.0, 4.0);

            self.position = vec3(new_x, new_y, self.position.z);
        }
    }

    on key_down(Key.Right) {
        key_right = true;
    }

    on key_up(Key.Right) {
        key_right = false;
    }

    on key_down(Key.Left) {
        key_left = true;
