        position: vec3(0.0, 1.0, 0.0);
    }

    entity Floor {
        mesh: Plane { size: vec3(14.0, 14.0, 1.0) };
        material: PbrMaterial { base_color: #9aa5b1; metallic: 0.0; roughness: 0.9 };
        position: vec3(0.0, 0.0, 0.0);
    }

    entity Lamp {
        position: vec3(1.5, 3.0, 2.5);
    }
}

material PbrMaterial {
    param base_color: color = #ffffff;
    param metallic: f32 = 0.0;
    param roughness: f32 = 0.5;

    fragment(input: SurfaceInput) -> color {
        let albedo = color.linear(base_color.rgb, base_color.a);
        let lamp_pos = vec3(1.5, 3.0, 2.5);
        let lamp_to_surface = lamp_pos - input.world_position;
        let distance = length(lamp_to_surface);
        let lamp_direction = normalize(lamp_to_surface);

        let surface_normal = normalize(input.normal);
        let cos_angle = max(0.0, dot(surface_normal, lamp_direction));

        let lamp_strength = 1.0 / (distance * distance);
        let point_light_intensity = lamp_strength * cos_angle;

        let ambient_strength = 0.05;
        let ambient_light = ambient_strength * albedo.rgb;

        let diffuse = point_light_intensity * albedo.rgb;
        let combined = (diffuse + ambient_light) * vec3(1.0, 1.0, 1.0);

        let result = lighting.pbr(input, albedo, metallic, roughness);

        return result;
    }
}
