    // Intensity = 1.0 / (3.0 * 3.0) = 1/9 ≈ 0.1111
    entity LampLeft {
        position: vec3(-3.0, 2.5, 2.0);
        light: PointLight {
            color: color.srgb(#ff3030);
            intensity: 0.1111;
        };
    }

