// Custom material that computes a color sweep based on object-space X coordinate and time
material Sweep {
    param time: f32 = 0.0;

    fragment(input: SurfaceInput) -> color {
        // Get the x coordinate in object space (ranges from -2 to 2 for a 4-wide box)
        let x = input.position.x;

        // Compute the blend weight: w = 0.5 + 0.5 * sin(0.8 * x + t)
        let w = 0.5 + 0.5 * sin(0.8 * x + time);

        // Color A: #1a237e in sRGB
        let colorA_srgb = vec3(26.0 / 255.0, 35.0 / 255.0, 126.0 / 255.0);
        let colorA_linear = color.linear(colorA_srgb, 1.0).rgb;

        // Color B: #ffb300 in sRGB
        let colorB_srgb = vec3(1.0, 179.0 / 255.0, 0.0);
        let colorB_linear = color.linear(colorB_srgb, 1.0).rgb;

        // Blend in linear light: (1 - w) * A + w * B
        let blended = (1.0 - w) * colorA_linear + w * colorB_linear;

        // Return as linear color (no conversion back to sRGB)
        return color.linear(blended, 1.0);
    }
}

