    light_color: vec3,
    base_color: vec3,
    roughness: f32
) -> vec3 {
    let n_dot_l = max(dot(normal, light_dir), 0.0);
    let diffuse = base_color * n_dot_l;

    let half_dir = normalize(view_dir + light_dir);
    let n_dot_h = max(dot(normal, half_dir), 0.0);

