// Scene with a white ball and floor lit by red and blue point lights and tinted ambient light

fn compute_pbr_lighting(
    normal: vec3,
    view_dir: vec3,
    light_dir: vec3,
    light_color: vec3,
    base_color: vec3,
    roughness: f32
) -> vec3 {
    let n_dot_l = max(dot(normal, light_dir), 0.0);
    let diffuse = base_color * n_dot_l;

    let half_dir = normalize(view_dir + light_dir);
    let n_dot_h = max(dot(normal, half_dir), 0.0);

    let alpha = roughness * roughness;
    let alpha2 = alpha * alpha;
    let n_dot_h2 = n_dot_h * n_dot_h;
    let denom = n_dot_h2 * (alpha2 - 1.0) + 1.0;
    let d = alpha2 / (3.14159 * denom * denom);

    let f0 = vec3(0.04, 0.04, 0.04);
    let fresnel = f0 + (vec3(1.0, 1.0, 1.0) - f0) * pow(1.0 - max(dot(half_dir, view_dir), 0.0), 5.0);

    let v_dot_h = max(dot(view_dir, half_dir), 0.0);
    let k = (roughness + 1.0) * (roughness + 1.0) / 8.0;
    let g_v = max(dot(normal, view_dir), 0.0) / (max(dot(normal, view_dir), 0.0) * (1.0 - k) + k);
    let g_l = n_dot_l / (n_dot_l * (1.0 - k) + k);
    let g = g_v * g_l;

    let specular = (d * fresnel * g) / max(4.0 * max(dot(normal, view_dir), 0.0) * n_dot_l, 0.001);

    return (diffuse + specular) * light_color * n_dot_l;
}

