const SWATCH_TEXTURE = asset.texture("assets/swatch.png");

material PlainMaterial {
    fragment(input: SurfaceInput) -> color {
        // Hard-edged sampling: nearest neighbor with repeat
        let sampler_nn = sampler.nearest_repeat();
        let uv = input.uv;
        let sampled = sample(SWATCH_TEXTURE, sampler_nn, uv);
        return color.srgb(sampled.rgb, sampled.a);
    }
}

material TiledMaterial {
    fragment(input: SurfaceInput) -> color {
        // Tiled 2x2: hard-edged, repeat naturally
        let sampler_nn = sampler.nearest_repeat();
        let uv = input.uv * 2.0;
        let sampled = sample(SWATCH_TEXTURE, sampler_nn, uv);
        return color.srgb(sampled.rgb, sampled.a);
    }
}

material SmoothMaterial {
    fragment(input: SurfaceInput) -> color {
        // Smoothly interpolated with clamping
        let sampler_linear = sampler.linear_clamp();
        let uv = input.uv;
        let sampled = sample(SWATCH_TEXTURE, sampler_linear, uv);
        return color.srgb(sampled.rgb, sampled.a);
    }
}
